Let  $q = \frac{3p-5}{2}$  where  $p$  is an odd prime, and let\[
S_q = \frac{1}{2\cdot 3 \cdot 4} + \frac{1}{5\cdot 6 \cdot 7} + \cdots + \frac{1}{q(q+1)(q+2)}
\]Prove that if  $\frac{1}{p}-2S_q = \frac{m}{n}$  for integers  $m$  and  $n$ , then  $m - n$  is divisible by  $p$ .

candidates:
Let  $H_n=\sum_{k=1}^n1/k$ . It is not hard to see that
\begin{align*}
    S_q&=\sum_{k=1}^{\frac12(p-1)}\frac1{3k(3k-1)(3k+1)}
        &=\sum_{k=1}^{\frac12(p-1)}\left(\frac{1/2}{3k-1}-\frac1{3k}+\frac{1/2}{3k+1}\right)
        &=\frac12\sum_{k=1}^{\frac12(p-1)}\left(\frac1{3k-1}+\frac1{3k}+\frac1{3k+1}\right)-\frac32\sum_{k=1}^{\frac12(p-1)}\frac1{3k}
        &=\frac12\left(H_{\frac12(3p-1)}-H_{\frac12(p-1)}-1\right),
\end{align*}
whence \[\frac mn=\frac1p-2S_q=\frac1p-\left(H_{\frac12(3p-1)}-H_{\frac12(p-1)}-1\right)=1-\left(\sum_{k=\frac12(p+1)}^{\frac12(3p-1)}\frac1k\right)+\frac1p.\]
Conveniently the  $1/p$  cancels out, so taking everything modulo  $p$ , \[\frac mn\equiv 1-\sum_{k=1}^{p-1}\frac1k\equiv 1-\sum_{k=1}^{p-1}k\equiv 1\pmod p,\]
i.e.\  $m-n\equiv 0\pmod p$ , as desired.

Observe the decomposition
\[\frac{1}{n(n+1)(n+2)} = \frac{1}{2n}+\frac{1}{2(n+2)} - \frac{1}{n+1}.\]
Hence, we have
\[S_q = \frac{1}{2}\sum_{2\le n\le \frac{3p-1}{2},3\nmid n}\frac{1}{n} - \sum_{1\le n\le \frac{3p-3}{2},3\mid n}\frac{1}{n}.\]
Rearranging yields
\[2S_q - \frac1p + 1=  \sum_{i=1,3\nmid i}^{p-1} \frac{1}{i}+\sum_{i=p+1,3\nmid i}^{q+2}\frac{1}{i}
- 2\sum_{i=1}^{\frac{q+1}{3}}\frac{1}{3i}=\sum_{i=1}^{p-1} \frac{1}{i}+\sum_{i=p+1}^{q+2}\frac{1}{i}
- 3\sum_{i=1}^{\frac{q+1}{3}}\frac{1}{3i}=\]
\[\sum_{i=1}^{p-1} \frac{1}{i}+\sum_{i=p+1}^{q+2}\frac{1}{i}
- \sum_{i=1}^{\frac{q+1}{3}}\frac{1}{i}.\]
Now, take modulo  $p$  to yield
\[1-\frac{m}{n} \equiv \sum_{i=1}^{p-1} \frac{1}{i}+\sum_{i=p+1}^{q+2}\frac{1}{i}
- \sum_{i=1}^{\frac{q+1}{3}}\frac{1}{i} \equiv \sum_{i=p+1}^{q+2}\frac{1}{i}
- \sum_{i=1}^{\frac{q+1}{3}}\frac{1}{i} \equiv \sum_{i=p+1}^{\frac{q+1}{3}}\frac{1}{i}
- \sum_{i=1}^{\frac{q+1}{3}}\frac{1}{i} \equiv 0\pmod{p},\]
hence 
\[m\equiv n\pmod{p}\]
and the conclusion follows.

We have
\begin{align*}
    2S_q &= 2\sum_{x=1}^{\frac{q+1}{3}} \frac{1}{(3x-1)(3x)(3x+1)} =  \sum_{x=1}^{\frac{p-1}{2}} \left[\frac{1}{3x(3x-1)}-\frac{1}{3x(3x+1)}\right]
    &=\sum_{x=1}^{\frac{p-1}{2}} \left[ \frac{1}{3x-1} - \frac{2}{3x} +\frac{1}{3x+1}\right] =  \sum_{x=1}^{\frac{p-1}{2}}\left[ \frac{1}{3x-1} + \frac{1}{3x} +\frac{1}{3x+1}\right] - \sum_{x=1}^{\frac{p-1}{2}} \frac{1}{x} 
    &= H_{\frac{3p-1}{2}}-1 - H_{\frac{p-1}{2}}
\end{align*}
Therefore, 
\begin{align*}
    2S_q-\frac{1}{p} &= \left(-1-\frac{1}{p}\right) + \frac{2}{p+1} + \frac{2}{p+3}+\cdots+\frac{2}{3p-1}
    &= -1-\frac{1}{p} + \left(\frac{2}{p+1} + \frac{2}{3p-1}\right) + \left(\frac{2}{p+3} + \frac{2}{3p-3}\right) +\cdots + \left(\frac{2}{2p-2} + \frac{2}{2p+2}\right) +\frac{2}{2p} 
    &\equiv -1 \pmod{p},
\end{align*}
since each of the paired fractions sum to 0 mod  $p$ . Finally, this means  $-m/n\equiv -1\pmod{p}$ , i.e.  $p\mid m-n$ .

Note that

\begin{align*}
2S_q & = 2\sum_{k=1}^{\frac{p-1}{2}} \frac{1}{(3k-1)(3k)(3k+1)}
& = 2\sum_{k=1}^{\frac{p-1}{2}} \left(\frac{\tfrac{1}{2}}{3k-1} - \frac{1}{3k} + \frac{\tfrac{1}{2}}{3k+1}\right)
& = \sum_{k=1}^{\frac{p-1}{2}} \frac{1}{3k-1} - \frac{2}{3k} + \frac{1}{3k+1}
& = \sum_{k=1}^{\frac{p-1}{2}} \frac{1}{3k-1} + \frac{1}{3k} + \frac{1}{3k+1} - \frac{3}{3k}
& = \sum_{k=2}^{\frac{3(p-1)}{2}} \frac{1}{k} - \sum_{k=1}^{\frac{p-1}{2}} \frac{1}{k}
& = -1 + \sum_{\frac{p+1}{2}}^{\frac{3(p-1)}{2}} \frac{1}{k}. 
\end{align*}

Therefore,

\begin{align*}
\frac{m}{n} & = \frac{1}{p} - 2S_q
& = \frac{1}{p} + 1 - \sum_{\frac{p+1}{2}}^{\frac{3(p-1)}{2}} \frac{1}{k}
\end{align*}

which implies that

\begin{align*}
