size(200);
defaultpen(fontsize(10pt));
int m = 7;
for (int i = 0; i <= m; ++i){
	draw((i-0.5, -0.5)--(i-0.5, m-0.5), grey);
    draw((-0.5, i-0.5)--(m-0.5, i-0.5), grey);
}
pair A, B, C, D, P, Q, R;
A = (0, 0);
B = (0, m-1);
C = (m-1, m-1);
D = (m-1, 0);
P = (2.5, 1.5);
Q = (0, 1.5);
R = (6, 1.5);
path a1, a2, a3, a4;
a1 = A--(0,1.5)--P--(2.5,-0.5);
a2 = (0,3)--(0,1.5)--(-0.5,1.5);
a3 = (6,1)--(6,1.5)--(6.5,1.5);
a4 = (6,2)--(6,1.5)--P--(2.5,6.5);
draw(a1, red+linewidth(0.9), EndArrow(TeXHead));
