<blockquote><u>*Solution.*</u> Let $ g(x):=f(x)-x^n $. By Lagrange Interpolation,

	\begin{eqnarray*}g(x)&=&\sum_{i=1}^ng(i)\prod_{1\leq j\leq n\atop j\neq i}\frac{x-j}{i-j}
	&=& \sum_{i=1}^n\frac{g(i)}{\prod_{1\leq j\leq n\atop j\neq i}(i-j)}\prod_{1\leq j\leq n\atop j\neq i}(x-j)
	&=& \sum_{i=1}^n\frac{g(i)(-1)^{n-i}}{(i-1)!(n-i)!}x^{n-1}\prod_{1\leq j\leq n\atop j\neq i}\left(1-\frac{j}{x}\right)
	\end{eqnarray*}.

	Dividing by $ x^{n-1} $ and taking $ x\rightarrow\infty $, we obtain
	\begin{eqnarray*}
	0 = \sum_{i=1}^n\frac{ig(i)(-1)^{n-i}}{\frac{n!}{\binom{n}{i}}}
	\end{eqnarray*},
	or equivalently,

	\begin{eqnarray*}
	\sum_{i=1}^n\binom{n}{i}(-1)^{n-i}i^{n+1}=\sum_{i=1}^ni\binom{n}{i}(-1)^{n-i}f(i)
	\end{eqnarray*}.

	It is not hard to prove (using Lagrange interpolation) that the left hand side is $ \frac{n(n+1)!}{2} $. If for all $ i\in [n] $, $ |f(i)|<\frac{n!}{\binom{n}{i}} $, then

	\begin{eqnarray*}
	\frac{n(n+1)!}{2}=\left| \sum_{i=1}^ni\binom{n}{i}(-1)^{n-i}f(i)\right|\leq \sum_{i=1}^ni\binom{n}{i}|f(i)|<n!\sum_{i=1}^ni=\frac{n(n+1)!}{2}
	\end{eqnarray*},

	a contradiction. $ \Box$
</blockquote>

